#!/usr/bin/env bash
# Create the parent testnet account from the faucet and sub-accounts with autogenerated keys in the OS
# keychain. Grammar: FACTS F-016/F-020 (near-cli-rs 0.31.1, --help confirmed 2026-11-10). Idempotent:
# existing accounts are skipped. The faucet gives the parent 10 NEAR (observed 2026-11-10), so balances
# are budgeted: light accounts now, contract accounts at deploy time sized from the built wasm.
# Usage: scripts/00-accounts.sh [light|contracts|all]   (default: light)
source "$(dirname "$0")/_lib.sh"; guard_mainnet
PARENT="${PARENT:-nectar.testnet}"
MODE="${1:-light}"
RPC="${NEAR_RPC_URL:-https://test.rpc.fastnear.com}"
# name:amount — contract amounts cover wasm storage (1E19 yocto/byte, F-014) + state headroom
LIGHT=(keeper:0.5 buyer1:0.5 buyer2:0.5 borrower1:0.5)
CONTRACTS=(usdc-mock:${MOCK_FT_NEAR:-2} nvdax-mock:${MOCK_FT_NEAR:-2} nectar-core:${CORE_NEAR:-4})

exists() {
  curl -s "$RPC" -H 'content-type: application/json' \
    -d "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"query\",\"params\":{\"request_type\":\"view_account\",\"finality\":\"final\",\"account_id\":\"$1\"}}" \
    | jq -e '.result.amount' >/dev/null
}

if ! exists "$PARENT"; then
  log "parent $PARENT via faucet (F-016)"
  retry near account create-account sponsor-by-faucet-service "$PARENT" \
    autogenerate-new-keypair --signature-scheme ed25519 save-to-keychain network-config testnet create </dev/null \
    || { echo "FAUCET FAILED ×${RETRIES:-5} → H-NEAR-FAUCET in docs/process/human-handoff.md" >&2; exit 2; }
fi

create_subs() {
  for spec in "$@"; do
    local s="${spec%%:*}" amt="${spec##*:}"
    if exists "$s.$PARENT"; then echo "skip $s.$PARENT (exists)"; continue; fi
    log "sub-account $s.$PARENT with $amt NEAR (F-020)"
    retry near account create-account fund-myself "$s.$PARENT" "$amt NEAR" \
      autogenerate-new-keypair --signature-scheme ed25519 save-to-keychain sign-as "$PARENT" \
      network-config testnet sign-with-keychain send </dev/null
  done
}

# (bash 3.2 on macOS: no `;;&`)
case "$MODE" in light|contracts|all) ;; *) echo "usage: $0 [light|contracts|all]" >&2; exit 2 ;; esac
[ "$MODE" = "contracts" ] || create_subs "${LIGHT[@]}"
[ "$MODE" = "light" ] || create_subs "${CONTRACTS[@]}"

if [ "$MODE" != "contracts" ]; then
  KEYS="$(curl -s "$RPC" -H 'content-type: application/json' -d "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"query\",\"params\":{\"request_type\":\"view_access_key_list\",\"finality\":\"final\",\"account_id\":\"keeper.$PARENT\"}}")"
  if echo "$KEYS" | jq -e '.result.keys[] | select(.access_key.permission | type == "object")' >/dev/null; then
    echo "skip keeper function-call key (exists)"
  else
    log "keeper function-call key (F-020; C-004; D-010: two methods only)"
    near account add-key "keeper.$PARENT" grant-function-call-access \
      --allowance '1 NEAR' --contract-account-id "nectar-core.$PARENT" \
      --function-names 'trigger_preliquidation,relay_settlement_result' \
      autogenerate-new-keypair --signature-scheme ed25519 save-to-keychain \
      network-config testnet sign-with-keychain send </dev/null
  fi
fi
mkdir -p ~/.nectar/keys && chmod 700 ~/.nectar ~/.nectar/keys
log "ids (orchestrator writes these to config.yaml + FACTS §Account ids)"
echo "PARENT=$PARENT"; for spec in "${LIGHT[@]}" "${CONTRACTS[@]}"; do s="${spec%%:*}"; if exists "$s.$PARENT"; then echo "$s=$s.$PARENT"; fi; done
